<div class="p-6 space-y-4"><h1 class="text-2xl font-bold">Promotions</h1><form wire:submit="save" class="grid grid-cols-3 gap-2"><select wire:model="student_id"><option value="">Student</option>@foreach($students as $student)<option value="{{$student->id}}">{{$student->first_name}} {{$student->last_name}}</option>@endforeach</select><select wire:model="source_enrollment_id"><option value="">Source enrollment</option>@foreach($enrollments as $enrollment)<option value="{{$enrollment->id}}">Year {{$enrollment->academic_year_id}} / Class {{$enrollment->class_id}}</option>@endforeach</select><select wire:model="target_academic_year_id"><option value="">Target year</option>@foreach($years as $year)<option value="{{$year->id}}">{{$year->name}}</option>@endforeach</select><select wire:model="target_class_id"><option value="">Target class</option>@foreach($classes as $class)<option value="{{$class->id}}">{{$class->name}}</option>@endforeach</select><button class="bg-blue-600 text-white p-2">Create draft</button></form><table class="w-full"><tbody>@forelse($promotions as $p)<tr><td>{{$p->student->first_name}} {{$p->student->last_name}}</td><td>{{$p->status}}</td><td>@if($p->status==='draft')<button wire:click="evaluate({{$p->id}})">Evaluate</button>@elseif($p->status==='eligible')<button wire:click="approve({{$p->id}})">Approve</button>@elseif($p->status==='approved')<button wire:click="apply({{$p->id}})">Apply</button>@endif</td></tr>@empty<tr><td>No promotions.</td></tr>@endforelse</tbody></table></div>
